declare(strict_types=1);

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

/**
 * Add only the DAV absence read surfaces to the existing NC34/35 fixtures, using the verbatim, hash-checked sources
 * that are byte-identical in server v34.0.4 and v35.0.1.
 * Usage: php tests/fixtures/nextcloud-api/generate-absence.php <34|35> [fixture output directory].
 * No network, source execution, server, SQL or unrelated fixture regeneration is involved.
 */
require __DIR__ . '/../../../vendor/autoload.php';
$major = $argv[1] ?? '';
if (!in_array($major, ['34', '35'], true)) throw new RuntimeException('Expected an absence fixture major: 34 or 35.');
$pins = json_decode((string)file_get_contents(__DIR__ . '/../absence-native/sources.json'), true, 512, JSON_THROW_ON_ERROR)['files'];
$target = ($argv[2] ?? __DIR__) . '/' . $major . '.php';
$tree = sys_get_temp_dir() . '/mcp-absence-api-' . bin2hex(random_bytes(6));
try {
	foreach ($pins as $file => $pin) {
		$source = __DIR__ . '/../absence-native/' . $file;
		if (hash_file('sha256', $source) !== $pin['sha256']) throw new RuntimeException('Absence source SHA256 mismatch: ' . $file);
		@mkdir(dirname($tree . '/' . $pin['path']), recursive: true);
		copy($source, $tree . '/' . $pin['path']);
	}
	$fixture = require $target;
	$parser = new SourceParser($tree);
	foreach (['OCA\\DAV\\Service\\AbsenceService', 'OCA\\DAV\\Db\\Absence', 'OCA\\DAV\\CalDAV\\TimezoneService', 'OCP\\User\\IAvailabilityCoordinator', 'OCP\\User\\IOutOfOfficeData'] as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) throw new RuntimeException('Missing pinned absence surface: ' . $class);
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$original = (string)file_get_contents($target);
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// Absence surfaces generated[^\n]*\n~', '', $header);
	$header .= "// Absence surfaces generated by generate-absence.php from server v34.0.4/v35.0.1 (byte-identical); URLs and SHAs in absence-native/sources.json.\n";
	FixtureFile::write($target, $header, $fixture);
	echo 'Generated five absence surfaces for NC' . $major . "\n";
} finally {
	$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
	foreach ($files as $file) $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
	rmdir($tree);
}
